const v1 = await (await fetch("http://[address]:18082/v1/disbursements")).json();
console.log("v1 count:", v1.disbursements.length);
let cursor = null, all = [], ids = new Set();
for (let i = 0; i < 100; i++) {
  const url = "http://[address]:18082/v2/disbursements" + (cursor ? "?cursor=" + encodeURIComponent(cursor) : "");
  const body = await (await fetch(url)).json();
  for (const d of body.disbursements) if (!ids.has(d.id)) { ids.add(d.id); all.push(d); }
  if (body.drained) { console.log("drained after", i+1, "windows, total:", all.length); break; }
  cursor = body.cursor;
}
const verify = await (await fetch("http://[address]:18082/v2/verify", {method:"POST", headers:{"content-type":"application/json"}, body: JSON.stringify({disbursements: all.map(d=>({id:d.id}))})})).json();
console.log(JSON.stringify(verify));
console.log(JSON.stringify(all[0]));
console.log(JSON.stringify(v1.disbursements[0]));
// compare v1 ids vs v2 ids
const v1ids = new Set(v1.disbursements.map(d=>d.id));
const missing = all.filter(d=>!v1ids.has(d.id)).length;
const extra = v1.disbursements.filter(d=>!ids.has(d.id)).length;
console.log({missing_in_v1: missing, extra_in_v1: extra});

